import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { StatusBar } from 'expo-status-bar';

import { RootStackParamList } from './navigation/types';
import HealthScreen from './screens/HealthScreen';
import HomeScreen from './screens/HomeScreen';
import TranscribeScreen from './screens/TranscribeScreen';

const Stack = createNativeStackNavigator<RootStackParamList>();

export default function App() {
  return (
    <NavigationContainer>
      <Stack.Navigator>
        <Stack.Screen name="Home" component={HomeScreen} options={{ title: 'Native Bench' }} />
        <Stack.Screen name="Health" component={HealthScreen} options={{ title: 'Health' }} />
        <Stack.Screen
          name="Transcribe"
          component={TranscribeScreen}
          options={{ title: 'Transcribe' }}
        />
      </Stack.Navigator>
      <StatusBar style="auto" />
    </NavigationContainer>
  );
}

import { StyleSheet, Text, View } from 'react-native';

import Button from '../components/Button';

export default function TranscribeScreen() {
  return (
    <View style={styles.container}>
      <Text style={styles.status}>Speech access: not requested</Text>

      <View style={styles.actions}>
        <Button title="Request Access" onPress={() => {}} />
        <Button title="Transcribe Sample" onPress={() => {}} disabled />
      </View>

      <View style={styles.transcriptArea}>
        <Text style={styles.emptyStateText}>No transcript yet</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    padding: 24,
  },
  status: {
    fontSize: 15,
    color: '#6E6E73',
    marginBottom: 20,
  },
  actions: {
    gap: 12,
  },
  transcriptArea: {
    marginTop: 32,
    flex: 1,
    alignItems: 'center',
    paddingVertical: 24,
  },
  emptyStateText: {
    fontSize: 15,
    color: '#8E8E93',
  },
});

