import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { StyleSheet, Text, View } from 'react-native';

import Button from '../components/Button';
import { RootStackParamList } from '../navigation/types';

type Props = NativeStackScreenProps<RootStackParamList, 'Home'>;

export default function HomeScreen({ navigation }: Props) {
  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>Native Bench</Text>
        <Text style={styles.subtitle}>Token economics benchmark</Text>
      </View>
      <View style={styles.actions}>
        <Button title="Health" onPress={() => navigation.navigate('Health')} />
        <Button title="Transcribe" onPress={() => navigation.navigate('Transcribe')} />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    padding: 24,
    justifyContent: 'space-between',
  },
  header: {
    marginTop: 48,
    alignItems: 'center',
  },
  title: {
    fontSize: 32,
    fontWeight: '700',
    color: '#1C1C1E',
  },
  subtitle: {
    marginTop: 8,
    fontSize: 17,
    color: '#6E6E73',
  },
  actions: {
    gap: 12,
    marginBottom: 24,
  },
});

