import ExpoModulesCore
import Speech

internal final class SpeechRecognizerUnavailableException: Exception {
  override var reason: String {
    "Speech recognizer is not available"
  }
}

internal final class SampleFileMissingException: Exception {
  override var reason: String {
    "Bundled sample audio file was not found"
  }
}

internal final class TranscriptionInProgressException: Exception {
  override var reason: String {
    "A transcription is already running"
  }
}

public class ExpoSpeechModule: Module {
  private var recognitionTask: SFSpeechRecognitionTask?

  public func definition() -> ModuleDefinition {
    Name("ExpoSpeech")

    Events("onPartialTranscript")

    AsyncFunction("getAuthorizationStatus") { () -> String in
      Self.authorizationStatusString(SFSpeechRecognizer.authorizationStatus())
    }

    AsyncFunction("requestAuthorization") { () async -> String in
      let status = await withCheckedContinuation { (continuation: CheckedContinuation<SFSpeechRecognizerAuthorizationStatus, Never>) in
        SFSpeechRecognizer.requestAuthorization { status in
          continuation.resume(returning: status)
        }
      }
      return Self.authorizationStatusString(status)
    }

    AsyncFunction("transcribeSample") { () async throws -> String in
      guard self.recognitionTask == nil else {
        throw TranscriptionInProgressException()
      }
      guard let fileUrl = Bundle.main.url(forResource: "sample", withExtension: "wav") else {
        throw SampleFileMissingException()
      }
      guard let recognizer = SFSpeechRecognizer(locale: Locale(identifier: "en-US")), recognizer.isAvailable else {
        throw SpeechRecognizerUnavailableException()
      }

      let request = SFSpeechURLRecognitionRequest(url: fileUrl)
      request.shouldReportPartialResults = true

      return try await withCheckedThrowingContinuation { continuation in
        var didResume = false
        self.recognitionTask = recognizer.recognitionTask(with: request) { result, error in
          if let error = error {
            if !didResume {
              didResume = true
              continuation.resume(throwing: error)
            }
            self.recognitionTask = nil
            return
          }
          guard let result = result else { return }
          self.sendEvent("onPartialTranscript", ["text": result.bestTranscription.formattedString])
          if result.isFinal {
            if !didResume {
              didResume = true
              continuation.resume(returning: result.bestTranscription.formattedString)
            }
            self.recognitionTask = nil
          }
        }
      }
    }
  }

  private static func authorizationStatusString(_ status: SFSpeechRecognizerAuthorizationStatus) -> String {
    switch status {
    case .notDetermined:
      return "notDetermined"
    case .authorized:
      return "authorized"
    case .denied, .restricted:
      return "denied"
    @unknown default:
      return "notDetermined"
    }
  }
}

