import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import Button from '../components/Button';
import { SpeechAuthorizationStatus } from '../modules/expo-speech/src/ExpoSpeech.types';
import ExpoSpeechModule from '../modules/expo-speech/src/ExpoSpeechModule';

const STATUS_LABELS: Record<SpeechAuthorizationStatus, string> = {
  notDetermined: 'Speech access: not requested',
  authorized: 'Speech access: granted',
  denied: 'Speech access: denied',
};

function toMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export default function TranscribeScreen() {
  const [status, setStatus] = useState<SpeechAuthorizationStatus>('notDetermined');
  const [error, setError] = useState<string | null>(null);
  const [running, setRunning] = useState(false);
  const [transcript, setTranscript] = useState<string | null>(null);
  const [elapsedSeconds, setElapsedSeconds] = useState<number | null>(null);

  useFocusEffect(
    useCallback(() => {
      let cancelled = false;
      (async () => {
        try {
          const current = await ExpoSpeechModule.getAuthorizationStatus();
          if (cancelled) return;
          setStatus(current);
          setError(null);
        } catch (e) {
          if (!cancelled) setError(toMessage(e));
        }
      })();
      return () => {
        cancelled = true;
      };
    }, [])
  );

  const handleRequestAccess = async () => {
    try {
      const next = await ExpoSpeechModule.requestAuthorization();
      setStatus(next);
      setError(null);
    } catch (e) {
      setError(toMessage(e));
    }
  };

  const handleTranscribe = async () => {
    setRunning(true);
    setError(null);
    setTranscript('');
    setElapsedSeconds(null);
    const startedAt = Date.now();
    const subscription = ExpoSpeechModule.addListener('onPartialTranscript', ({ text }) => {
      setTranscript(text);
    });
    try {
      const final = await ExpoSpeechModule.transcribeSample();
      setTranscript(final);
      setElapsedSeconds((Date.now() - startedAt) / 1000);
    } catch (e) {
      setError(toMessage(e));
    } finally {
      subscription.remove();
      setRunning(false);
    }
  };

  const statusText = error ?? (running ? 'Transcribing…' : STATUS_LABELS[status]);

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{statusText}</Text>

      <View style={styles.actions}>
        <Button title="Request Access" onPress={handleRequestAccess} />
        <Button
          title="Transcribe Sample"
          onPress={handleTranscribe}
          disabled={status !== 'authorized' || running}
        />
      </View>

      <View style={styles.transcriptArea}>
        {transcript === null ? (
          <Text style={styles.emptyStateText}>No transcript yet</Text>
        ) : (
          <View style={styles.transcriptContent}>
            <Text style={styles.transcriptText}>{transcript}</Text>
            {elapsedSeconds !== null && (
              <Text style={styles.completedText}>Completed in {elapsedSeconds.toFixed(1)} s</Text>
            )}
          </View>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    padding: 24,
  },
  status: {
    fontSize: 15,
    color: '#6E6E73',
    marginBottom: 20,
  },
  actions: {
    gap: 12,
  },
  transcriptArea: {
    marginTop: 32,
    flex: 1,
    alignItems: 'center',
    paddingVertical: 24,
  },
  transcriptContent: {
    alignSelf: 'stretch',
  },
  transcriptText: {
    fontSize: 17,
    lineHeight: 24,
    color: '#1C1C1E',
  },
  completedText: {
    marginTop: 12,
    fontSize: 14,
    color: '#6E6E73',
  },
  emptyStateText: {
    fontSize: 15,
    color: '#8E8E93',
  },
});

